import type { MapId, MapPos } from './world.js';
import { WorldManager } from './world.js';
import { showPlateauMapRenderer } from './mapRenderer.web.js';
import { DEFAULT_FOREST_ENTRY, FOREST_MAPS } from './maps.js';

type PersistedWorldMapState = {
	mapId: MapId;
	pos: MapPos;
};

type WorldMapStateKey = 'forest' | 'boaraven';

function getWorldMapStatesStore(hero: any): Record<string, PersistedWorldMapState> {
	if (!hero) return {};
	if (!(hero as any).__worldMapStates || typeof (hero as any).__worldMapStates !== 'object') {
		(hero as any).__worldMapStates = {};
	}
	return (hero as any).__worldMapStates as Record<string, PersistedWorldMapState>;
}

function getHeroForWorldMaps(): any {
	return (window as any).game?.hero;
}

function readPersistedState(key: WorldMapStateKey): PersistedWorldMapState | null {
	const hero = getHeroForWorldMaps();
	const raw = getWorldMapStatesStore(hero)?.[key];
	if (!raw || typeof raw !== 'object') return null;
	const mapId = String((raw as any).mapId ?? '') as MapId;
	const x = Math.floor(Number((raw as any).pos?.x));
	const y = Math.floor(Number((raw as any).pos?.y));
	if (!mapId || !Number.isFinite(x) || !Number.isFinite(y)) return null;
	return { mapId, pos: { x, y } };
}

function persistState(key: WorldMapStateKey, state: PersistedWorldMapState): void {
	const hero = getHeroForWorldMaps();
	if (!hero) return;
	const store = getWorldMapStatesStore(hero);
	store[key] = {
		mapId: state.mapId,
		pos: { x: Math.floor(Number(state.pos.x)), y: Math.floor(Number(state.pos.y)) },
	};
}

export type WorldMapOptions = {
	onBack: () => void;
	startMapId?: MapId;
	startEntry?: MapPos;
};

export function showForestWorldMaps(options: WorldMapOptions): void {
	const world = new WorldManager();
	world.registerMaps(FOREST_MAPS);

	const persisted = readPersistedState('forest');
	const mapId = (options.startMapId ?? persisted?.mapId ?? 'forest_1') as MapId;
	const entry = options.startEntry ?? persisted?.pos ?? DEFAULT_FOREST_ENTRY;

	showPlateauMapRenderer({
		world,
		onBack: () => {
			persistState('forest', { mapId: world.currentMapId, pos: world.playerPos });
			options.onBack();
		},
		start: { mapId, entry },
		movement: { stepMs: 220 },
		// Layout intentionally omitted: we centralize world-map rendering defaults
		// inside the renderer and per-map meta (only for exceptional cases).
	});
	
}

export function showBoaravenWorldMap(options: WorldMapOptions): void {
	const world = new WorldManager();
	world.registerMaps(FOREST_MAPS);

	const persisted = readPersistedState('boaraven');
	const mapId = (options.startMapId ?? persisted?.mapId ?? 'village_y0x1') as MapId;
	const entry = options.startEntry ?? persisted?.pos ?? { x: 4, y: 4 };

	showPlateauMapRenderer({
		world,
		onBack: () => {
			persistState('boaraven', { mapId: world.currentMapId, pos: world.playerPos });
			options.onBack();
		},
		start: { mapId, entry },
		movement: { stepMs: 220 },
	});
}
