import { hero } from './index.web.js';
import { createSkill } from './skillLibrary.js';
import { dialogueManager, startDialogue } from './dialogue/dialogueManager.web.js';
import type { DialogueScript } from './dialogue/dialogueTypes.js';
import { resetPartyRuntime, getPartyMembers, setSelectedPartyIndex } from './party.web.js';
import { QuestManager } from './questManager.js';
import { QUEST_DEFS } from './quests.js';
import { addHonneur, addHumanite, addLiberte } from './virtues.js';
import { ensureTitles } from './titles.js';
import { showBoaravenWorldMap } from './world/worldMap.web.js';

type NewGameOptions = {
    onCancel?: () => void;
    onBackAfterStart?: () => void;
};

type PartyBond = 'freres' | 'amis' | 'prodiges';
type PartyLeader = 'guerrier' | 'voleur' | 'mage';
type DepartureGift = 'gold' | 'skill-points';

type CreationState = {
    bond: PartyBond | null;
    leader: PartyLeader | null;
    gift: DepartureGift | null;
};

const BASE_CHARACTERISTICS = {
    force: 10,
    sante: 10,
    energie: 6,
    vitesse: 2,
    magie: 4,
    critique: 0,
    defense: 0,
};

function renderBondLabel(bond: PartyBond | null): string {
    if (bond === 'freres') return 'Trois freres';
    if (bond === 'amis') return 'Trois amis';
    if (bond === 'prodiges') return 'Trois prodiges choisis par le village';
    return 'Lien non choisi';
}

function renderLeaderLabel(leader: PartyLeader | null): string {
    if (leader === 'guerrier') return 'Le guerrier';
    if (leader === 'voleur') return 'Le voleur';
    if (leader === 'mage') return 'Le mage';
    return 'Chef non choisi';
}

function renderGiftLabel(gift: DepartureGift | null): string {
    if (gift === 'gold') return '150 argent pour le depart';
    if (gift === 'skill-points') return '1 point de competence pour chaque personnage';
    return 'Don non choisi';
}

function resetHeroForNewGame(): void {
    hero.pv = 0;
    hero.maxPv = 0;
    hero.baseAttack = 0;
    hero.maxMana = 0;
    hero.currentMana = 0;
    hero.manaRegenPerTurn = 30;
    hero.level = 1;
    hero.currentXP = 0;
    hero.gold = 50;
    hero.wood = 10;
    hero.herb = 10;
    (hero as any).cuir = 10;
    (hero as any).fer = 10;
    hero.skillPoints = 0;
    hero.characteristicPoints = 0;
    hero.skills = [
        createSkill('basic_attack'),
        createSkill('block'),
        createSkill('mana_gain'),
        createSkill('missile_magique'),
    ];
    hero.passiveSkills = [];
    hero.activeEffects = [];
    hero.skillCooldowns = {};
    hero.inventory = [];
    hero.equipment = { weapon: undefined, armor: undefined, ring: undefined } as any;
    hero.actionPointsMax = 2;
    hero.actionPoints = 2;
    (hero as any).characterClass = 'guerrier';
    (hero as any).characteristics = { ...BASE_CHARACTERISTICS };
    (hero as any).learnedSkillIds = [];
    (hero as any).specializationPoints = { guerrier: 0, mage: 0, voleur: 0 };
    (hero as any).honneur = 0;
    (hero as any).liberte = 0;
    (hero as any).humanite = 0;
    (hero as any).titles = ['Mendiant'];
    (hero as any).quests = {};
    (hero as any).enigmes = {};
    (hero as any).market = undefined;
    (hero as any).marketDay = 1;
    (hero as any).day = 1;
    (hero as any).hour = 0;
    (hero as any).__worldEncounterDefeats = {};
    (hero as any).__worldMapStates = {};
    (hero as any).__partyBond = undefined;
    (hero as any).__partyLeader = undefined;
    (hero as any).__startingGift = undefined;
    (hero as any).__partyProgress = undefined;
    (hero as any).__hasStartedGame = false;
    hero.syncDerivedStatsFromCharacteristics({ fillResources: true });
}

function applyCreationChoices(state: CreationState): void {
    resetHeroForNewGame();
    resetPartyRuntime();

    (hero as any).__partyBond = state.bond;
    (hero as any).__partyLeader = state.leader;
    (hero as any).__startingGift = state.gift;
    (hero as any).__hasStartedGame = true;

    if (state.leader === 'guerrier') addHonneur(hero, 10);
    if (state.leader === 'voleur') addLiberte(hero, 10);
    if (state.leader === 'mage') addHumanite(hero, 10);

    if (state.gift === 'gold') {
        hero.gold = 150;
    }

    const members = getPartyMembers();

    if (state.gift === 'skill-points') {
        for (const member of members) {
            member.skillPoints = Math.max(0, Math.floor(Number(member.skillPoints ?? 0))) + 1;
        }
    }

    if (state.leader === 'mage') setSelectedPartyIndex(1);
    else if (state.leader === 'voleur') setSelectedPartyIndex(2);
    else setSelectedPartyIndex(0);

    ensureTitles(hero as any);
    const game = (window as any).game;
    if (game) {
        game.hero = hero;
        game.questManager = new QuestManager(hero, QUEST_DEFS);
    }
}

function buildCreationScript(state: CreationState, options: NewGameOptions): DialogueScript {
    return {
        id: 'new_game_character_creation',
        start: 'intro',
        nodes: {
            intro: {
                id: 'intro',
                speaker: 'Le chroniqueur',
                side: 'left',
                text: 'La route vers Boaraven s ouvre devant vous. Avant votre premier pas, une derniere question demeure : qui etes-vous, vraiment ?',
                choices: [{ text: 'Nous sommes prets.', next: 'bond' }],
            },
            bond: {
                id: 'bond',
                speaker: 'Le chroniqueur',
                side: 'left',
                text: 'Quel lien unit les trois aventuriers de votre groupe ?',
                choicesLayout: 'grid-3',
                choices: [
                    {
                        text: '3 Frères',
                        onSelect: () => {
                            state.bond = 'freres';
                        },
                        next: 'leader',
                    },
                    {
                        text: '3 Amis',
                        onSelect: () => {
                            state.bond = 'amis';
                        },
                        next: 'leader',
                    },
                    {
                        text: '3 Prodiges choisis par le village',
                        onSelect: () => {
                            state.bond = 'prodiges';
                        },
                        next: 'leader',
                    },
                ],
            },
            leader: {
                id: 'leader',
                speaker: 'Le chroniqueur',
                side: 'left',
                text: 'Qui porte la voix du groupe au moment du depart ?',
                choicesLayout: 'grid-3',
                choices: [
                    {
                        text: 'Le guerrier (+10 Honneur)',
                        onSelect: () => {
                            state.leader = 'guerrier';
                        },
                        next: 'gift',
                    },
                    {
                        text: 'Le voleur (+10 Liberte)',
                        onSelect: () => {
                            state.leader = 'voleur';
                        },
                        next: 'gift',
                    },
                    {
                        text: 'Le mage (+10 Humanite)',
                        onSelect: () => {
                            state.leader = 'mage';
                        },
                        next: 'gift',
                    },
                ],
            },
            gift: {
                id: 'gift',
                speaker: "L'ancien du village",
                side: 'right',
                text: 'Que vous a t on confie pour votre depart ?',
                choices: [
                    {
                        text: '150 argent',
                        onSelect: () => {
                            state.gift = 'gold';
                        },
                        next: 'final',
                    },
                    {
                        text: '1 point de competence pour chaque personnage',
                        onSelect: () => {
                            state.gift = 'skill-points';
                        },
                        next: 'final',
                    },
                ],
            },
            final: {
                id: 'final',
                speaker: 'Le chroniqueur',
                side: 'left',
                text: `${renderBondLabel(state.bond)}. ${renderLeaderLabel(state.leader)} guidera la compagnie. Pour le depart : ${renderGiftLabel(state.gift)}.\n\nLes portes s ouvrent. Boaraven vous attend.`,
                choices: [
                    {
                        text: 'Entrer dans Boaraven',
                        onSelect: () => {
                            applyCreationChoices(state);
                            window.setTimeout(() => {
                                showBoaravenWorldMap({ onBack: options.onBackAfterStart ?? options.onCancel ?? (() => {}) });
                            }, 0);
                        },
                    },
                ],
            },
        },
    };
}

export function showNewGameCreation(options: NewGameOptions = {}): void {
    const app = document.getElementById('app');
    if (!app) return;

    const state: CreationState = {
        bond: null,
        leader: null,
        gift: null,
    };

    app.innerHTML = `
        <img src="ImagesRPG/imagesfond/fond_saint_michel.avif" class="background" alt="Creation de personnage">
        <div class="centered-content" style="max-width:min(860px, 92vw);">
            <div style="background:rgba(8,10,18,0.70);border:1px solid rgba(255,255,255,0.16);border-radius:20px;padding:28px 24px;box-shadow:0 24px 70px rgba(0,0,0,0.45);backdrop-filter:blur(5px);">
                <div style="font-size:0.95em;letter-spacing:0.28em;text-transform:uppercase;color:rgba(255,230,170,0.86);margin-bottom:10px;">Nouvelle partie</div>
                <h1 style="margin:0 0 10px 0;font-family:'Cinzel','Georgia',serif;">Creation du groupe</h1>
                <p style="margin:0 auto 14px auto;max-width:680px;line-height:1.6;color:#f2eee4;">
                    Une seule fois, avant votre premier voyage, le destin du groupe se fixe. Les choix faits ici definiront l origine de la compagnie et l elan de son depart.
                </p>
                <div style="display:flex;gap:12px;justify-content:center;flex-wrap:wrap;margin-top:18px;">
                    <button class="btn" id="startCharacterCreationBtn" style="min-width:240px;">Commencer la creation</button>
                    <button class="btn" id="cancelCharacterCreationBtn" style="min-width:220px;">Retour accueil</button>
                </div>
                <div style="margin-top:18px;padding-top:16px;border-top:1px solid rgba(255,255,255,0.10);color:#d9d1bc;font-size:0.95em;line-height:1.6;">
                    <div><b>Questions prevues :</b> lien du groupe, chef de la compagnie, don de depart.</div>
                    <div><b>Arrivee :</b> la carte de Boaraven, directement apres le dernier choix.</div>
                </div>
            </div>
        </div>
    `;

    const launchDialogue = () => {
        startDialogue(buildCreationScript(state, options), {
            hero,
            questManager: (window as any).game?.questManager,
        });
    };

    document.getElementById('startCharacterCreationBtn')?.addEventListener('click', launchDialogue);
    document.getElementById('cancelCharacterCreationBtn')?.addEventListener('click', () => {
        dialogueManager.close();
        options.onCancel?.();
    });
}