import { getPartyMembers } from '../party.web.js';
import { showTemporaryMessage } from '../uiNotifications.js';
import { CRAFT_RECIPES, type CraftCategory, type CraftCost, type CraftRecipe } from './craftRecipes.js';
import { runForgeMinigame } from './forgeMinigame.web.js';
import { runSewingMinigame } from './sewingMinigame.web.js';
import { runOtherMinigame } from './otherMinigame.web.js';

const FABRICATION_MODAL_ID = 'fabricationWorldModal';

type FabricationModalOptions = {
	onClose?: () => void;
};

const CATEGORY_META: Array<{ id: 'all' | CraftCategory; label: string }> = [
	{ id: 'all', label: 'Tout' },
	{ id: 'equipment', label: 'Équipement' },
	{ id: 'consumable', label: 'Consommables' },
	{ id: 'other', label: 'Autres' },
];

const getCraftHero = (): any => (getPartyMembers()[0] as any) ?? (window as any).game?.hero ?? null;

const getResourceAmount = (hero: any, key: keyof CraftCost): number => Math.max(0, Math.floor(Number(hero?.[key] ?? 0)));

const hasResources = (hero: any, cost: CraftCost): boolean => {
	return getResourceAmount(hero, 'wood') >= Math.max(0, Math.floor(Number(cost.wood ?? 0)))
		&& getResourceAmount(hero, 'herb') >= Math.max(0, Math.floor(Number(cost.herb ?? 0)))
		&& getResourceAmount(hero, 'cuir') >= Math.max(0, Math.floor(Number(cost.cuir ?? 0)))
		&& getResourceAmount(hero, 'fer') >= Math.max(0, Math.floor(Number(cost.fer ?? 0)));
};

const consumeCost = (hero: any, cost: CraftCost): void => {
	hero.wood = Math.max(0, getResourceAmount(hero, 'wood') - Math.max(0, Math.floor(Number(cost.wood ?? 0))));
	hero.herb = Math.max(0, getResourceAmount(hero, 'herb') - Math.max(0, Math.floor(Number(cost.herb ?? 0))));
	hero.cuir = Math.max(0, getResourceAmount(hero, 'cuir') - Math.max(0, Math.floor(Number(cost.cuir ?? 0))));
	hero.fer = Math.max(0, getResourceAmount(hero, 'fer') - Math.max(0, Math.floor(Number(cost.fer ?? 0))));
};

const costLabel = (cost: CraftCost): string => {
	const parts: string[] = [];
	if (cost.wood) parts.push(`${Math.floor(Number(cost.wood))} bois`);
	if (cost.herb) parts.push(`${Math.floor(Number(cost.herb))} herbes`);
	if (cost.cuir) parts.push(`${Math.floor(Number(cost.cuir))} cuir`);
	if (cost.fer) parts.push(`${Math.floor(Number(cost.fer))} fer`);
	return parts.join(' + ') || 'gratuit';
};

const addCraftedItems = (hero: any, recipe: CraftRecipe, craftedCount: number, score?: number, quality?: number): { itemName: string; craftedCount: number } => {
	const count = Math.max(0, Math.floor(Number(craftedCount ?? 0)));
	if (count <= 0) return { itemName: String(recipe.label), craftedCount: 0 };

	const first = recipe.create();
	const isStackable = Boolean((first as any)?.stackable) || recipe.category === 'consumable';
	const itemName = String((first as any)?.name ?? recipe.label);

	if (typeof score === 'number') (first as any).fabricationScore = score;
	if (typeof quality === 'number') (first as any).fabricationQuality = quality;

	if (isStackable) {
		(first as any).quantity = count;
		hero.addItem(first);
		if (String(recipe.id ?? '') === 'campfire') {
			try {
				(window as any).game?.questManager?.emit?.({ type: 'create_campfire' });
			} catch {
				// noop
			}
		}
		return { itemName, craftedCount: count };
	}

	hero.addItem(first);
	if (String(recipe.id ?? '') === 'campfire') {
		try {
			(window as any).game?.questManager?.emit?.({ type: 'create_campfire' });
		} catch {
			// noop
		}
	}
	for (let i = 1; i < count; i++) {
		const extra = recipe.create();
		if (typeof score === 'number') (extra as any).fabricationScore = score;
		if (typeof quality === 'number') (extra as any).fabricationQuality = quality;
		hero.addItem(extra);
	}

	return { itemName, craftedCount: count };
};

export function showFabricationModal(options: FabricationModalOptions = {}): void {
	if (document.getElementById(FABRICATION_MODAL_ID)) return;

	const hero = getCraftHero();
	if (!hero) {
		showTemporaryMessage('Aucun personnage.', 1600);
		return;
	}

	const root = document.createElement('div');
	root.id = FABRICATION_MODAL_ID;
	root.style.cssText = [
		'position:fixed',
		'inset:0',
		'background:rgba(0,0,0,0.68)',
		'display:flex',
		'align-items:center',
		'justify-content:center',
		'padding:16px',
		'z-index:18000',
	].join(';');

	const panel = document.createElement('div');
	panel.style.cssText = [
		'width:min(860px, 96vw)',
		'max-height:min(88vh, 860px)',
		'overflow:auto',
		'background:rgba(17,17,17,0.96)',
		'border:1px solid rgba(255,255,255,0.10)',
		'border-radius:16px',
		'padding:16px',
		'color:#fff',
		'box-shadow:0 12px 40px rgba(0,0,0,0.55)',
	].join(';');

	const close = () => {
		try { root.remove(); } catch { /* noop */ }
		try { options.onClose?.(); } catch { /* noop */ }
	};

	const reopen = () => {
		window.setTimeout(() => showFabricationModal(options), 0);
	};

	let selectedCategory: 'all' | CraftCategory = 'all';

	const render = () => {
		const resources = `Bois: ${getResourceAmount(hero, 'wood')} • Herbes: ${getResourceAmount(hero, 'herb')} • Cuir: ${getResourceAmount(hero, 'cuir')} • Fer: ${getResourceAmount(hero, 'fer')}`;
		const visibleRecipes = CRAFT_RECIPES.filter((recipe) => selectedCategory === 'all' || recipe.category === selectedCategory);
		panel.innerHTML = `
			<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;">
				<div>
					<div style="font-size:20px;font-weight:900;">Fabrication</div>
					<div style="margin-top:4px;color:#bbb;">${resources}</div>
				</div>
				<button class="btn" id="fabricationCloseBtn">Fermer</button>
			</div>
			<div id="fabricationCategories" style="margin-top:14px;display:flex;gap:8px;flex-wrap:wrap;"></div>
			<div id="fabricationRecipeList" style="margin-top:14px;display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px;"></div>
		`;

		const categoriesEl = panel.querySelector('#fabricationCategories') as HTMLDivElement | null;
		if (categoriesEl) {
			categoriesEl.innerHTML = CATEGORY_META.map((category) => {
				const isActive = category.id === selectedCategory;
				const count = CRAFT_RECIPES.filter((recipe) => category.id === 'all' || recipe.category === category.id).length;
				return `
					<button
						type="button"
						data-craft-category="${category.id}"
						style="padding:8px 12px;border-radius:999px;border:1px solid ${isActive ? 'rgba(255,215,120,0.45)' : 'rgba(255,255,255,0.10)'};background:${isActive ? 'rgba(255,215,120,0.16)' : 'rgba(255,255,255,0.04)'};color:#fff;cursor:pointer;font-weight:${isActive ? '800' : '600'};">
						${category.label} (${count})
					</button>
				`;
			}).join('');
		}

		const list = panel.querySelector('#fabricationRecipeList') as HTMLDivElement | null;
		if (list) {
			list.innerHTML = visibleRecipes.map((recipe) => {
				const affordable = hasResources(hero, recipe.cost);
				return `
					<div style="border:1px solid rgba(255,255,255,0.08);border-radius:14px;padding:12px;background:rgba(255,255,255,0.04);display:flex;flex-direction:column;gap:10px;">
						<div>
							<div style="font-weight:800;">${recipe.label}</div>
							<div style="margin-top:4px;color:#d8c39d;font-size:12px;font-weight:700;">Catégorie: ${CATEGORY_META.find((entry) => entry.id === recipe.category)?.label ?? recipe.category}</div>
							<div style="margin-top:4px;color:#bbb;font-size:12px;">Coût: ${costLabel(recipe.cost)}</div>
							<div style="margin-top:4px;color:#999;font-size:12px;">Atelier: ${recipe.minigame ?? 'direct'}</div>
						</div>
						<button class="btn" data-craft-id="${recipe.id}" ${affordable ? '' : 'disabled'}>Fabriquer</button>
					</div>
				`;
			}).join('') || '<div style="padding:18px;border-radius:14px;background:rgba(255,255,255,0.04);color:#bbb;">Aucun objet dans cette catégorie.</div>';
		}

		panel.querySelector('#fabricationCloseBtn')?.addEventListener('click', close);
		(panel.querySelectorAll('[data-craft-category]') as NodeListOf<HTMLButtonElement>).forEach((button) => {
			button.addEventListener('click', () => {
				const next = String(button.dataset.craftCategory ?? 'all') as 'all' | CraftCategory;
				selectedCategory = next;
				render();
			});
		});
		(panel.querySelectorAll('[data-craft-id]') as NodeListOf<HTMLButtonElement>).forEach((button) => {
			button.addEventListener('click', async () => {
				const recipeId = String(button.dataset.craftId ?? '');
				const recipe = CRAFT_RECIPES.find((entry) => entry.id === recipeId);
				if (!recipe) return;
				if (!hasResources(hero, recipe.cost)) {
					showTemporaryMessage('Ressources insuffisantes.', 1800);
					render();
					return;
				}

				close();

				if (recipe.minigame === 'forge') {
					await runForgeMinigame({
						recipeLabel: recipe.label,
						onCancel: () => { showTemporaryMessage('Fabrication annulée.', 1600); },
						onCraft: async (result, _probs, chosenQuality) => {
							consumeCost(hero, recipe.cost);
							const created = addCraftedItems(hero, recipe, 1, result.totalScore, chosenQuality);
							showTemporaryMessage(`Création effectuée: ${created.itemName}`, 2800);
							return { itemName: created.itemName };
						},
					});
					reopen();
					return;
				}

				if (recipe.minigame === 'sewing') {
					await runSewingMinigame({
						recipeLabel: recipe.label,
						onCancel: () => { showTemporaryMessage('Fabrication annulée.', 1600); },
						onPartialFail: () => {
							consumeCost(hero, recipe.cost);
							showTemporaryMessage('Découpe ratée: matériaux perdus.', 2400);
						},
						onCraft: async (result, _probs, chosenQuality) => {
							consumeCost(hero, recipe.cost);
							const created = addCraftedItems(hero, recipe, 1, result.totalScore, chosenQuality);
							showTemporaryMessage(`Création effectuée: ${created.itemName}`, 2800);
							return { itemName: created.itemName };
						},
					});
					reopen();
					return;
				}

				if (recipe.minigame === 'memory') {
					await runOtherMinigame({
						recipeLabel: recipe.label,
						onCancel: () => { showTemporaryMessage('Fabrication annulée.', 1600); },
						onCraft: async (result) => {
							if (result.pairsFound <= 0) {
								showTemporaryMessage('Aucune paire trouvée: aucun objet créé.', 2200);
								return { itemName: recipe.label, craftedCount: 0 };
							}
							consumeCost(hero, recipe.cost);
							const created = addCraftedItems(hero, recipe, result.pairsFound, result.points);
							showTemporaryMessage(`Création effectuée: ${created.itemName} x${created.craftedCount}`, 2800);
							return { itemName: created.itemName, craftedCount: created.craftedCount };
						},
					});
					reopen();
					return;
				}

				consumeCost(hero, recipe.cost);
				const created = addCraftedItems(hero, recipe, 1);
				showTemporaryMessage(`Création effectuée: ${created.itemName}`, 2600);
				reopen();
			});
		});
	};

	root.addEventListener('click', (event) => {
		if (event.target === root) close();
	});

	root.appendChild(panel);
	document.body.appendChild(root);
	render();
}