// Affichage de l'écran d'accueil
import { showCombat } from './combat.web.js';
import { hero } from './index.web.js';
import {
    type BrowserSaveMeta,
    deleteBrowserSave,
    exportSaveAsString,
    importSaveFromString,
    listBrowserSaveSlots,
    loadGameFromBrowser,
    SAVE_SLOT_COUNT,
    saveGameToBrowser,
} from './save.web.js';
import { showTacticalSkirmish } from './tacticalCombat.web.js';
import { showNewGameCreation } from './newGame.web.js';
import { showBoaravenWorldMap } from './world/worldMap.web.js';

function formatSaveDate(value: string): string {
    if (!value) return 'date inconnue';
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? 'date inconnue' : date.toLocaleString();
}

function buildSaveSlotSummaryHtml(meta: BrowserSaveMeta | null): string {
    if (!meta) return '<div style="color:#aaa;">Emplacement vide</div>';
    return `
        <div style="font-weight:800;color:#fff;">${meta.heroName}</div>
        <div style="font-size:0.92em;color:#ddd;">Niveau ${meta.level}</div>
        <div style="font-size:0.88em;color:#bbb;">${formatSaveDate(meta.createdAt)}</div>
    `;
}

function openSaveSlotsModal() {
    const overlay = document.createElement('div');
    overlay.style.cssText = [
        'position:fixed',
        'inset:0',
        'background:rgba(0,0,0,0.72)',
        'z-index:1200',
        'display:flex',
        'align-items:center',
        'justify-content:center',
        'padding:16px',
    ].join(';');

    const panel = document.createElement('div');
    panel.style.cssText = [
        'width:min(960px, 96vw)',
        'max-height:88vh',
        'overflow:auto',
        'background:rgba(10,10,18,0.96)',
        'border:1px solid rgba(255,255,255,0.14)',
        'border-radius:16px',
        'box-shadow:0 24px 80px rgba(0,0,0,0.5)',
        'padding:18px',
        'color:#fff',
    ].join(';');

    const close = () => {
        overlay.remove();
        showAccueil();
    };

    const render = () => {
        const slots = listBrowserSaveSlots();
        panel.innerHTML = `
            <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px;">
                <div>
                    <div style="font-size:1.2em;font-weight:900;">Sauvegardes</div>
                    <div style="color:#bbb;font-size:0.95em;">Choisis un emplacement pour sauvegarder, charger ou supprimer.</div>
                </div>
                <button class="btn" id="closeSaveSlotsModalBtn" style="min-width:96px;">Fermer</button>
            </div>
            <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;">
                ${slots
                    .map(({ slot, meta }) => `
                        <div style="background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.10);border-radius:14px;padding:14px;display:flex;flex-direction:column;gap:12px;">
                            <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;">
                                <div>
                                    <div style="font-size:1.05em;font-weight:900;">Emplacement ${slot}</div>
                                    ${buildSaveSlotSummaryHtml(meta)}
                                </div>
                            </div>
                            <div style="display:flex;flex-wrap:wrap;gap:8px;">
                                <button class="btn" data-save-slot="${slot}" style="min-width:110px;">Sauvegarder</button>
                                <button class="btn" data-load-slot="${slot}" style="min-width:110px;" ${meta ? '' : 'disabled'}>Charger</button>
                                <button class="btn" data-delete-slot="${slot}" style="min-width:110px;" ${meta ? '' : 'disabled'}>Supprimer</button>
                            </div>
                        </div>
                    `)
                    .join('')}
            </div>
        `;

        panel.querySelector('#closeSaveSlotsModalBtn')?.addEventListener('click', close);

        (panel.querySelectorAll('[data-save-slot]') as NodeListOf<HTMLButtonElement>).forEach((btn) => {
            btn.addEventListener('click', () => {
                const slot = Number(btn.getAttribute('data-save-slot'));
                const meta = slots.find((entry) => entry.slot === slot)?.meta ?? null;
                if (meta && !window.confirm(`Écraser l'emplacement ${slot} ?`)) return;
                const res = saveGameToBrowser(hero, slot);
                if (!res.ok) {
                    alert('Erreur sauvegarde: ' + res.error);
                    return;
                }
                render();
            });
        });

        (panel.querySelectorAll('[data-load-slot]') as NodeListOf<HTMLButtonElement>).forEach((btn) => {
            btn.addEventListener('click', () => {
                const slot = Number(btn.getAttribute('data-load-slot'));
                const res = loadGameFromBrowser(hero, slot);
                if (!res.ok) {
                    alert('Erreur chargement: ' + res.error);
                    return;
                }
                alert(`Sauvegarde chargée depuis l'emplacement ${slot}.`);
                close();
            });
        });

        (panel.querySelectorAll('[data-delete-slot]') as NodeListOf<HTMLButtonElement>).forEach((btn) => {
            btn.addEventListener('click', () => {
                const slot = Number(btn.getAttribute('data-delete-slot'));
                if (!window.confirm(`Supprimer la sauvegarde de l'emplacement ${slot} ?`)) return;
                const res = deleteBrowserSave(slot);
                if (!res.ok) {
                    alert('Erreur suppression: ' + res.error);
                    return;
                }
                render();
            });
        });
    };

    overlay.addEventListener('click', (event) => {
        if (event.target === overlay) close();
    });

    overlay.appendChild(panel);
    document.body.appendChild(overlay);
    render();
}

function confirmStartNewGame(): boolean {
    return window.confirm(
        'Attention : si vous continuez, la partie en cours non sauvegardee sera supprimee.\n\nPensez a sauvegarder avant de lancer une nouvelle partie.\n\nContinuer ?'
    );
}

export function showAccueil() {
        // Supprime le bouton Fuir du DOM si présent
        const fuirBtn = document.getElementById('fuirBtn');
        if (fuirBtn && document.body.contains(fuirBtn)) document.body.removeChild(fuirBtn);
    const app = document.getElementById('app');
    if (!app) return;
    // Ask for name if hero keeps the default
    // (No persistence across browser restarts — name remains only for current session)
    const askNameHtml = (hero.name === 'Hero' || !hero.name) ? `
            <div style="margin-bottom:14px;">
                <label for="nameInput">Entrez votre prénom :</label><br>
                <input id="nameInput" type="text" placeholder="Ton prénom" style="padding:8px 10px;border-radius:6px;border:1px solid rgba(255,255,255,0.08);min-width:220px;margin-top:8px;">
                <div style="margin-top:10px;"><button class="btn" id="submitNameBtn">Valider</button></div>
            </div>
        ` : `
            <div id="playerGreeting" style="margin-bottom:14px;">Bienvenue, <b>${hero.name}</b> !</div>
        `; 

    const saveSlots = listBrowserSaveSlots();
    const usedSlots = saveSlots.filter((entry) => entry.meta).length;
    const latestSave = saveSlots
        .filter((entry) => entry.meta)
        .map((entry) => entry.meta as BrowserSaveMeta)
        .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())[0] ?? null;
    const canResume = Boolean((hero as any).__hasStartedGame);
    const saveInfoHtml = usedSlots > 0
        ? `<div style="margin-top:10px;font-size:0.95em;color:#ddd;">${usedSlots}/${SAVE_SLOT_COUNT} emplacement(s) utilisé(s)${latestSave ? ` · Dernière sauvegarde : ${latestSave.heroName}, ${formatSaveDate(latestSave.createdAt)}` : ''}</div>`
        : `<div style="margin-top:10px;font-size:0.95em;color:#bbb;">Aucune sauvegarde détectée</div>`;

    app.innerHTML = `
        <img src="ImagesRPG/imagesfond/fondaccueil.png" class="background" alt="Accueil RPG">
        <div class="centered-content">
            <h1>Bienvenue dans le jeu RPG !</h1>
            ${askNameHtml}
            <button class="btn" id="newGameBtn">Nouvelle partie</button>
            <button class="btn" id="resumeGameBtn" ${canResume ? '' : 'disabled style="opacity:0.5;cursor:not-allowed;"'}>Reprendre la partie</button>
            <button class="btn" id="villageBtn" disabled style="opacity:0.5;cursor:not-allowed;">Village</button>

            <div style="margin-top:18px; padding-top:10px; border-top:1px solid rgba(255,255,255,0.08);">
                <h2 style="margin:0 0 10px 0; font-size:1.15em; font-weight:600;">Sauvegarde</h2>
                ${saveInfoHtml}
                <button class="btn" id="saveSlotsBtn">Gérer les sauvegardes</button>
                <button class="btn" id="exportBtn">Exporter</button>
                <button class="btn" id="importBtn">Importer</button>
            </div>
        </div>
    `;

    // Name input handlers
    if (hero.name === 'Hero' || !hero.name) {
        const submitBtn = document.getElementById('submitNameBtn');
        const nameInput = document.getElementById('nameInput') as HTMLInputElement | null;
        submitBtn?.addEventListener('click', () => {
            if (!nameInput) return;
            const val = nameInput.value.trim();
            if (val.length === 0) {
                alert('Veuillez entrer votre prénom.');
                return;
            }
            // Keep name in-memory only for this session
            hero.name = val;
            // Re-render accueil to show greeting
            showAccueil();
        });
        if (nameInput) {
            nameInput.addEventListener('keyup', (e: KeyboardEvent) => {
                if (e.key === 'Enter') {
                    (document.getElementById('submitNameBtn') as HTMLButtonElement)?.click();
                }
            });
        }
    }

    document.getElementById('newGameBtn')?.addEventListener('click', () => {
        if (!confirmStartNewGame()) return;
        showNewGameCreation({ onCancel: showAccueil, onBackAfterStart: showAccueil });
    });
    if (canResume) {
        document.getElementById('resumeGameBtn')?.addEventListener('click', () => {
            showBoaravenWorldMap({ onBack: showAccueil });
        });
    }

    document.getElementById('saveSlotsBtn')?.addEventListener('click', openSaveSlotsModal);

    document.getElementById('exportBtn')?.addEventListener('click', async () => {
        const text = exportSaveAsString(hero);
        try {
            if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
                await navigator.clipboard.writeText(text);
                alert('Export copié dans le presse-papiers.');
                return;
            }
        } catch {
            // ignore and fallback to prompt
        }
        // Fallback: show in prompt for manual copy
        window.prompt('Copiez votre sauvegarde JSON :', text);
    });

    document.getElementById('importBtn')?.addEventListener('click', () => {
        const input = window.prompt('Collez votre sauvegarde JSON :');
        if (!input) return;
        const slotInput = window.prompt(`Importer dans quel emplacement ? (1-${SAVE_SLOT_COUNT})`, '1');
        if (!slotInput) return;
        const slot = Number(slotInput);
        if (!Number.isInteger(slot) || slot < 1 || slot > SAVE_SLOT_COUNT) {
            alert(`Emplacement invalide. Choisissez un nombre entre 1 et ${SAVE_SLOT_COUNT}.`);
            return;
        }
        const res = importSaveFromString(hero, input, slot);
        if (!res.ok) {
            alert('Erreur import: ' + res.error);
            return;
        }
        alert(`Sauvegarde importée dans l'emplacement ${slot} et chargée.`);
        showAccueil();
    });
}
