import { escapeHtml } from './utils.web.js';

export type JukeboxTrackDef = {
	id: string;
	name: string;
	description: string;
	audioKey: string;
	price: number;
	ownedByDefault?: boolean;
};

export const JUKEBOX_TRACKS: JukeboxTrackDef[] = [
	{
		id: 'auberge_theme',
		name: "Ambiance de l'auberge",
		description: "Le morceau habituel de l'auberge.",
		audioKey: 'auberge',
		price: 0,
		ownedByDefault: true,
	},
	{
		id: 'boaraven_ballad',
		name: 'Ballade de Boaraven',
		description: 'Une variation plus calme basee sur la musique principale.',
		audioKey: 'background',
		price: 10,
	},
	{
		id: 'mozart_piano_concerto_23_adagio',
		name: 'Mozart : Piano Concerto No 23 - Adagio',
		description: 'Un adagio pour transformer l\'auberge en veritable salon musical.',
		audioKey: 'mozart_piano_concerto_23_adagio',
		price: 10,
	},
];

type JukeboxHeroState = {
	__jukeboxOwnedTrackIds?: string[];
	__selectedJukeboxTrackId?: string;
	gold?: number;
};

type MusicListModalOptions = {
	hero: JukeboxHeroState | null | undefined;
	notify?: (message: string, ms?: number) => void;
};

let musicListModalEl: HTMLDivElement | null = null;

const DEFAULT_TRACK_ID = JUKEBOX_TRACKS.find((track) => track.ownedByDefault)?.id ?? JUKEBOX_TRACKS[0]?.id ?? '';

function getTrackById(trackId: string | null | undefined): JukeboxTrackDef | undefined {
	const normalized = String(trackId ?? '').trim();
	if (!normalized) return undefined;
	return JUKEBOX_TRACKS.find((track) => track.id === normalized);
}

function getDefaultOwnedTrackIds(): string[] {
	return JUKEBOX_TRACKS.filter((track) => track.ownedByDefault).map((track) => track.id);
}

function getHeroState(hero: JukeboxHeroState | null | undefined): Required<Pick<JukeboxHeroState, '__jukeboxOwnedTrackIds' | '__selectedJukeboxTrackId'>> | null {
	if (!hero) return null;
	const defaults = getDefaultOwnedTrackIds();
	const owned = Array.isArray(hero.__jukeboxOwnedTrackIds)
		? hero.__jukeboxOwnedTrackIds.map((trackId) => String(trackId ?? '').trim()).filter(Boolean)
		: [];
	const mergedOwned = Array.from(new Set([...defaults, ...owned]));
	if (!mergedOwned.length && DEFAULT_TRACK_ID) mergedOwned.push(DEFAULT_TRACK_ID);
	hero.__jukeboxOwnedTrackIds = mergedOwned;
	const current = String(hero.__selectedJukeboxTrackId ?? '').trim();
	hero.__selectedJukeboxTrackId = mergedOwned.includes(current) ? current : (mergedOwned[0] ?? DEFAULT_TRACK_ID);
	return {
		__jukeboxOwnedTrackIds: hero.__jukeboxOwnedTrackIds,
		__selectedJukeboxTrackId: hero.__selectedJukeboxTrackId,
	};
}

export function getOwnedJukeboxTrackIds(hero: JukeboxHeroState | null | undefined): string[] {
	return [...(getHeroState(hero)?.__jukeboxOwnedTrackIds ?? [])];
}

export function isJukeboxTrackOwned(hero: JukeboxHeroState | null | undefined, trackId: string): boolean {
	return getOwnedJukeboxTrackIds(hero).includes(String(trackId ?? '').trim());
}

export function getSelectedJukeboxTrackId(hero: JukeboxHeroState | null | undefined): string {
	return String(getHeroState(hero)?.__selectedJukeboxTrackId ?? DEFAULT_TRACK_ID);
}

export function getSelectedJukeboxTrack(hero: JukeboxHeroState | null | undefined): JukeboxTrackDef | undefined {
	return getTrackById(getSelectedJukeboxTrackId(hero)) ?? getTrackById(DEFAULT_TRACK_ID);
}

export function setSelectedJukeboxTrack(hero: JukeboxHeroState | null | undefined, trackId: string): { ok: true; track: JukeboxTrackDef } | { ok: false; error: string } {
	const track = getTrackById(trackId);
	if (!hero || !track) return { ok: false, error: 'Musique introuvable.' };
	if (!isJukeboxTrackOwned(hero, track.id)) return { ok: false, error: 'Cette musique doit d\'abord etre achetee.' };
	getHeroState(hero);
	hero.__selectedJukeboxTrackId = track.id;
	return { ok: true, track };
}

export function purchaseJukeboxTrack(hero: JukeboxHeroState | null | undefined, trackId: string): { ok: true; track: JukeboxTrackDef; spent: number } | { ok: false; error: string } {
	const track = getTrackById(trackId);
	if (!hero || !track) return { ok: false, error: 'Musique introuvable.' };
	if (isJukeboxTrackOwned(hero, track.id)) return { ok: false, error: 'Vous possedez deja cette musique.' };
	const price = Math.max(0, Math.floor(Number(track.price ?? 0)));
	const gold = Math.max(0, Math.floor(Number(hero.gold ?? 0)));
	if (gold < price) return { ok: false, error: `Pas assez d'argent (${price} requis).` };
	hero.gold = gold - price;
	const owned = getOwnedJukeboxTrackIds(hero);
	hero.__jukeboxOwnedTrackIds = Array.from(new Set([...owned, track.id]));
	if (!hero.__selectedJukeboxTrackId) hero.__selectedJukeboxTrackId = track.id;
	return { ok: true, track, spent: price };
}

export function playSelectedJukeboxTrack(hero: JukeboxHeroState | null | undefined, audioManager: any): JukeboxTrackDef | undefined {
	const track = getSelectedJukeboxTrack(hero);
	if (!track) return undefined;
	const isPlaying = typeof audioManager?.isPlaying === 'function' ? Boolean(audioManager.isPlaying(track.audioKey)) : false;
	if (!isPlaying) {
		if (typeof audioManager?.pauseAllLooping === 'function') audioManager.pauseAllLooping(track.audioKey);
		else if (typeof audioManager?.pauseAll === 'function') audioManager.pauseAll(track.audioKey);
		if (typeof audioManager?.play === 'function') audioManager.play(track.audioKey);
	}
	return track;
}

export const closeMusicListModal = (): void => {
	musicListModalEl?.remove();
	musicListModalEl = null;
};

export const openMusicListModal = (options: MusicListModalOptions): void => {
	const hero = options.hero;
	if (!hero) {
		options.notify?.('Hero introuvable.', 2600);
		return;
	}

	if (musicListModalEl) {
		closeMusicListModal();
	}

	const notify = (message: string, ms = 2800) => {
		try {
			options.notify?.(message, ms);
		} catch {
			// noop
		}
	};

	musicListModalEl = document.createElement('div');
	musicListModalEl.id = 'musicListModal';
	musicListModalEl.style.cssText = [
		'position:fixed',
		'inset:0',
		'display:flex',
		'align-items:center',
		'justify-content:center',
		'background:rgba(0,0,0,0.72)',
		'z-index:10000',
		'padding:18px',
	].join(';');

	const panel = document.createElement('div');
	panel.style.cssText = [
		'width:min(860px, 96vw)',
		'max-height:min(84vh, 820px)',
		'overflow:auto',
		'background:linear-gradient(180deg, #18120e 0%, #0f0d0b 100%)',
		'border:1px solid rgba(255,215,120,0.18)',
		'border-radius:14px',
		'padding:16px',
		'color:#fff7ea',
		'box-shadow:0 24px 50px rgba(0,0,0,0.45)',
	].join(';');

	const renderModal = () => {
		const owned = new Set(getOwnedJukeboxTrackIds(hero));
		const selectedTrackId = getSelectedJukeboxTrackId(hero);
		const gold = Math.max(0, Math.floor(Number(hero.gold ?? 0)));

		panel.innerHTML = `
			<div style="display:flex;gap:12px;align-items:center;justify-content:space-between;">
				<div>
					<div style="font-weight:900;font-size:20px;">Liste de musiques</div>
					<div style="color:#d4c4ac;margin-top:4px;">Le pianiste te laisse acheter de nouveaux morceaux pour le jukebox.</div>
				</div>
				<button class="btn" id="musicListModalCloseBtn">Fermer</button>
			</div>
			<div style="margin-top:12px;padding:12px 14px;border-radius:12px;background:rgba(255,255,255,0.05);display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;">
				<div>Argent disponible : <b>${gold}</b></div>
				<div>Piste active : <b>${escapeHtml(String(getSelectedJukeboxTrack(hero)?.name ?? 'Aucune'))}</b></div>
			</div>
			<div style="display:flex;flex-direction:column;gap:12px;margin-top:14px;">
				${JUKEBOX_TRACKS.map((track) => {
					const isOwned = owned.has(track.id);
					const isSelected = selectedTrackId === track.id;
					const canAfford = gold >= track.price;
					const priceLabel = track.price <= 0 ? 'Inclus' : `${track.price} argent`;
					const statusLabel = isSelected ? 'En lecture' : (isOwned ? 'Possedee' : 'A acheter');
					return `
						<div style="background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.08);padding:14px;border-radius:12px;display:flex;justify-content:space-between;gap:14px;align-items:center;">
							<div style="min-width:0;flex:1;">
								<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;">
									<div style="font-weight:800;font-size:1.05em;">${escapeHtml(track.name)}</div>
									<span style="font-size:0.86em;padding:4px 8px;border-radius:999px;background:${isSelected ? 'rgba(127, 255, 180, 0.14)' : 'rgba(255,255,255,0.08)'};color:${isSelected ? '#b8ffd7' : '#e7d5bb'};">${escapeHtml(statusLabel)}</span>
								</div>
								<div style="color:#d7c6ae;margin-top:6px;">${escapeHtml(track.description)}</div>
								<div style="color:#b7a58b;font-size:0.92em;margin-top:8px;">Tarif : ${escapeHtml(priceLabel)}</div>
							</div>
							<div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;">
								${isOwned
									? `<button class="btn" data-action="play" data-track-id="${escapeHtml(track.id)}" ${isSelected ? 'disabled' : ''}>${isSelected ? 'En cours' : 'Jouer'}</button>`
									: `<button class="btn" data-action="buy" data-track-id="${escapeHtml(track.id)}" ${canAfford ? '' : 'disabled'}>Acheter</button>`}
							</div>
						</div>
					`;
				}).join('')}
			</div>
		`;

		(panel.querySelector('#musicListModalCloseBtn') as HTMLButtonElement | null)?.addEventListener('click', () => {
			closeMusicListModal();
		});

		Array.from(panel.querySelectorAll<HTMLButtonElement>('button[data-action][data-track-id]')).forEach((button) => {
			button.addEventListener('click', () => {
				const action = String(button.dataset.action ?? '').trim();
				const trackId = String(button.dataset.trackId ?? '').trim();
				if (!trackId) return;

				if (action === 'buy') {
					const result = purchaseJukeboxTrack(hero, trackId);
					if (!result.ok) {
						notify(result.error, 3000);
						return;
					}
					notify(`Musique achetee : ${result.track.name} (-${result.spent} argent)`, 3200);
					renderModal();
					return;
				}

				if (action === 'play') {
					const result = setSelectedJukeboxTrack(hero, trackId);
					if (!result.ok) {
						notify(result.error, 3000);
						return;
					}
					playSelectedJukeboxTrack(hero, (window as any).game?.audioManager);
					notify(`Lecture : ${result.track.name}`, 2600);
					renderModal();
				}
			});
		});
	};

	renderModal();
	musicListModalEl.appendChild(panel);
	musicListModalEl.addEventListener('click', (event) => {
		if (event.target === musicListModalEl) closeMusicListModal();
	});
	document.body.appendChild(musicListModalEl);
};