function notify(ctx: DialogueContext, message: string, ms = 3500): void {
    try {
        ctx.notify?.(message, ms);
    } catch {
        // noop
    }
}

function tryStartQuest(ctx: DialogueContext, questId: string): void {
    try {
        const qm = ctx.questManager;
        if (!qm?.start) return;
        qm.start(questId);
    } catch {
        // noop
    }
}

function isQuestClaimed(ctx: DialogueContext, id: string): boolean {
    try {
        const p = ctx.questManager?.getProgress?.(id);
        return p?.status === 'claimed';
    } catch {
        return false;
    }
}

function isQuestActiveOrDone(ctx: DialogueContext, id: string): boolean {
    try {
        const p = ctx.questManager?.getProgress?.(id);
        return Boolean(p);
    } catch {
        return false;
    }
}

function isQuestCompletedOrClaimed(ctx: DialogueContext, id: string): boolean {
    try {
        const p = ctx.questManager?.getProgress?.(id);
        return p?.status === 'completed' || p?.status === 'claimed';
    } catch {
        return false;
    }
}

function isQuestCompleted(ctx: DialogueContext, id: string): boolean {
    try {
        const p = ctx.questManager?.getProgress?.(id);
        return p?.status === 'completed';
    } catch {
        return false;
    }
}

function questPreviewText(ctx: DialogueContext, questId: string): string {
    const entry = ((ctx.questManager?.getAll?.() ?? []) as any[]).find((item) => String(item?.def?.id ?? '') === questId);
    const def = entry?.def as any;
    if (!def) return 'Quête indisponible.';

    const rewardParts: string[] = [];
    const rewards = (def.rewards ?? {}) as Record<string, unknown>;
    const pushReward = (label: string, value: unknown) => {
        const amount = Math.max(0, Math.floor(Number(value ?? 0)));
        if (amount > 0) rewardParts.push(`${amount} ${label}`);
    };
    pushReward('XP', rewards.xp);
    pushReward('argent', rewards.gold);
    pushReward('bois', rewards.wood);
    pushReward('herbe(s)', rewards.herb);
    pushReward('point(s) de compétence', rewards.skillPoints);
    pushReward('feu(x) de camp', rewards.campfire);

    const rewardText = rewardParts.length ? rewardParts.join(', ') : 'Aucune récompense.';
    return `${String(def.description ?? '').trim() || 'Quête.'}\n\nRécompenses : ${rewardText}`;
}

function tryClaimQuest(ctx: DialogueContext, questId: string, successMessage?: string): void {
    try {
        const res = ctx.questManager?.claim?.(questId);
        if (res && (res as any).ok === false) {
            notify(ctx, String((res as any).error ?? 'Impossible de valider.'), 3500);
            return;
        }
        const rewardText = String((res as any)?.rewardText ?? '').trim();
        const baseMessage = successMessage ?? `Quête validée : ${String((res as any)?.questName ?? '').trim() || questId}`;
        notify(ctx, rewardText ? `${baseMessage} — ${rewardText}` : baseMessage, 3200);
    } catch {
        notify(ctx, 'Erreur de validation.', 2600);
    }
}

